```{.r .cell-code}
m_2x2 <- lm(reformulate(c("joven", "ola", "joven:post"), y_var), data = did_2x2)
m_2x2_edad <- lm(reformulate(c("factor(edad_nac)", "ola", "joven:post"), y_var), data = did_2x2)
m_twfe <- lm(reformulate(c("educacion_ciudadana", "factor(edad_nac)", "ola"), y_var), data = did_df)
m_2x2_sinplan <- lm(reformulate(c("factor(edad_nac)", "ola", "joven:post"), y_var), data = did_2x2_sinplan)

args_did <- list(list(m_2x2, m_2x2_edad, m_twfe, m_2x2_sinplan),
                 custom.model.names = c("2x2", "2x2 con EF edad", "EF edad y ola",
                                        "2x2 con EF edad, controles sin Plan"))
do.call(texreg::htmlreg, c(args_did, file = paste0("output/tables/", prefijo, "_did_2x2.html")))

## Errores HC1 y agrupados por celda ----------------------------------------------
modelos_2x2 <- list("2x2" = m_2x2, "2x2 con EF edad" = m_2x2_edad,
                    "2x2 con EF edad, controles sin Plan" = m_2x2_sinplan)
cts_2x2 <- lapply(modelos_2x2, function(m) {
  list(hc1 = lmtest::coeftest(m, vcov. = sandwich::vcovHC, type = "HC1"),
       celda = lmtest::coeftest(m, vcov. = sandwich::vcovCL, cluster = ~celda, type = "HC1"))
})

# Coeficiente de joven:post, para el .rds
errores_2x2 <- dplyr::bind_rows(lapply(cts_2x2, function(ct) {
  data.frame(estimacion = ct$hc1["joven:post", 1],
             ee_hc1 = ct$hc1["joven:post", 2], p_hc1 = ct$hc1["joven:post", 4],
             ee_celda = ct$celda["joven:post", 2], p_celda = ct$celda["joven:post", 4])
}), .id = "modelo")
rownames(errores_2x2) <- NULL

cts_2x2 <- unlist(cts_2x2, recursive = FALSE)
args_errores_2x2 <- list(rep(unname(modelos_2x2), each = 2),
                         custom.model.names = paste(rep(names(modelos_2x2), each = 2), c("(HC1)", "(celda)")),
                         override.se = lapply(cts_2x2, function(ct) ct[, 2]),
                         override.pvalues = lapply(cts_2x2, function(ct) ct[, 4]),
                         custom.note = "%stars. Errores estándar HC1 o agrupados por celda de edad y ola entre paréntesis.")
do.call(texreg::htmlreg, c(args_errores_2x2, file = paste0("output/tables/", prefijo, "_did_2x2_errores.html")))
